<script setup lang="ts">
import { computed, ref } from 'vue'
import { useRouter } from 'vue-router'
import { ArrowRight } from 'lucide-vue-next'
import { useI18n } from 'vue-i18n'
import { useUserStore } from '@/stores'
import { BrandLogo, LanguageSwitch, ThemeToggle } from '@/components/ui'

const router = useRouter()
const userStore = useUserStore()
const { t } = useI18n()
const email = ref(''); const username = ref(''); const password = ref(''); const confirmPassword = ref(''); const verificationCode = ref(''); const error = ref(''); const isLoading = ref(false); const isSendingCode = ref(false); const countdown = ref(0)
const countdownText = computed(() => countdown.value > 0 ? t('auth.resendIn', { seconds: countdown.value }) : t('auth.sendCode'))
const canSendCode = computed(() => Boolean(email.value && /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email.value) && !countdown.value && !isSendingCode.value))
async function handleSendCode() { if (!canSendCode.value) return; isSendingCode.value = true; error.value = ''; try { const result = await userStore.sendVerificationCode(email.value); if (result.success) { countdown.value = 60; const timer = setInterval(() => { countdown.value--; if (countdown.value <= 0) clearInterval(timer) }, 1000); if (result.message.includes('开发模式')) alert(result.message) } else error.value = result.message } catch { error.value = t('auth.sendFailed') } finally { isSendingCode.value = false } }
async function handleRegister() { if (!email.value || !username.value || !password.value || !verificationCode.value) { error.value = t('auth.allRequired'); return } if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email.value)) { error.value = t('auth.invalidEmail'); return } if (password.value !== confirmPassword.value) { error.value = t('auth.passwordMismatch'); return } if (password.value.length < 10) { error.value = t('auth.passwordTooShort'); return } if (verificationCode.value.length !== 6) { error.value = t('auth.invalidCode'); return } isLoading.value = true; error.value = ''; try { await userStore.register(email.value, username.value, password.value, verificationCode.value); router.push('/') } catch { error.value = t('auth.registerFailed') } finally { isLoading.value = false } }
</script>

<template>
  <main class="min-h-screen bg-[var(--color-background)] p-5"><div class="mx-auto flex max-w-6xl items-center justify-between"><BrandLogo /><div class="flex gap-2"><LanguageSwitch /><ThemeToggle /></div></div><div class="mx-auto my-10 w-full max-w-lg"><section class="panel overflow-hidden"><div class="border-b p-6" style="border-color: var(--color-border)"><p class="page-eyebrow">HyperZone</p><h1 class="mt-2 text-2xl font-bold text-slate-950 dark:text-white">{{ t('auth.createAccount') }}</h1><p class="mt-1 text-sm text-slate-500">{{ t('auth.registerHint') }}</p></div><form class="space-y-4 p-6" @submit.prevent="handleRegister"><label><span class="field-label">{{ t('auth.email') }}</span><div class="flex gap-2"><input v-model="email" type="email" class="input flex-1" :placeholder="t('auth.emailPlaceholder')" required /><button type="button" class="btn btn-secondary shrink-0" :disabled="!canSendCode" @click="handleSendCode">{{ isSendingCode ? t('common.loading') : countdownText }}</button></div></label><label><span class="field-label">{{ t('auth.verificationCode') }}</span><input v-model="verificationCode" class="input" maxlength="6" :placeholder="t('auth.codePlaceholder')" required /></label><label><span class="field-label">{{ t('auth.username') }}</span><input v-model="username" class="input" :placeholder="t('auth.usernamePlaceholder')" required /></label><div class="grid gap-4 sm:grid-cols-2"><label><span class="field-label">{{ t('auth.password') }}</span><input v-model="password" type="password" class="input" :placeholder="t('auth.passwordNewPlaceholder')" required /></label><label><span class="field-label">{{ t('auth.confirmPassword') }}</span><input v-model="confirmPassword" type="password" class="input" :placeholder="t('auth.passwordConfirmPlaceholder')" required /></label></div><div v-if="error" class="rounded-md border border-red-200 bg-red-50 px-3 py-2 text-sm text-red-700 dark:border-red-900 dark:bg-red-950 dark:text-red-300">{{ error }}</div><button type="submit" class="btn btn-primary w-full" :disabled="isLoading">{{ isLoading ? t('auth.registering') : t('auth.register') }}<ArrowRight v-if="!isLoading" class="h-4 w-4" /></button></form></section><p class="mt-6 text-center text-sm text-slate-500">{{ t('auth.haveAccount') }} <RouterLink to="/login" class="font-semibold text-orange-600 dark:text-orange-400">{{ t('auth.loginNow') }}</RouterLink></p><p class="mt-3 text-center text-xs text-slate-400">{{ t('auth.agreement') }}</p></div></main>
</template>
